/**
 * diagnosis-archive.ts — 诊断归档
 *
 * 提供：
 *   - 诊断报告持久化（自包含 HTML）
 *   - 跨会话索引与检索
 *   - 知识提取（从历史诊断中提取可复用洞察）
 *   - 时间线聚合
 */
import type { StructuredDiagnosisReport } from './types';
/** 归档条目 */
export interface ArchiveEntry {
    /** 唯一标识 */
    id: string;
    /** 团队 ID */
    teamId: string;
    /** 诊断时间 */
    timestamp: string;
    /** 报告摘要（CEO 一句话） */
    summary: string;
    /** 最高风险的三个维度 */
    topRiskDimensions: string[];
    /** 关键指标快照 */
    metrics: Record<string, number>;
    /** 完整报告 */
    report: StructuredDiagnosisReport;
    /** 标签（便于检索） */
    tags: string[];
}
/** 归档查询过滤 */
export interface ArchiveFilter {
    teamId?: string;
    from?: string;
    to?: string;
    tags?: string[];
    /** 关键词搜索（匹配摘要和标签） */
    keyword?: string;
    /** 按时间排序 */
    order?: 'asc' | 'desc';
    limit?: number;
}
/** 跨诊断知识提取 */
export interface ExtractedKnowledge {
    /** 识别出的持久性模式 */
    persistentPatterns: string[];
    /** 重复出现的缝隙维度 */
    recurringDimensions: string[];
    /** 已改善的维度（对比历史） */
    improvedDimensions: string[];
    /** 恶化的维度 */
    degradedDimensions: string[];
    /** 上次修复方案的采纳率 */
    actionAdoptionRate: number;
    /** 团队成熟度趋势 -1（退化）到 +1（进步） */
    maturityTrend: number;
}
/** 归档一个诊断报告 */
export declare function archiveDiagnosis(report: StructuredDiagnosisReport, teamId: string, tags?: string[]): ArchiveEntry;
export declare function getArchive(id: string): ArchiveEntry | null;
/** 查询归档 */
export declare function queryArchives(filter?: ArchiveFilter): ArchiveEntry[];
/** 获取团队诊断历史 */
export declare function getTeamHistory(teamId: string, limit?: number): ArchiveEntry[];
/** 最新一次诊断 */
export declare function getLatestDiagnosis(teamId: string): ArchiveEntry | null;
/** 清理过期归档 */
export declare function cleanupArchive(maxAgeMs: number): number;
/** 重置归档存储（测试用） */
export declare function resetArchive(): void;
/** 从历史归档中提取可复用知识 */
export declare function extractKnowledge(teamId: string): ExtractedKnowledge;
